using System;
using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "BattleActionWithMinimumAstriumAction", menuName = "Data/Battle/Battle Actions/Orion/BattleActionWithMinimumAstrium Action")]
public class BattleActionWithMinimumAstriumAction : BattleAction
{
	[Header("Minimun Astrium Action")]
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	[HideIf("variableMinimumAstriumAmount")]
	private int minimumAstriumAmount;

	[SerializeField]
	private bool variableMinimumAstriumAmount;

	[SerializeField]
	private int astriumCost;

	[SerializeField]
	private bool disableAstriumCostDescription;

	[SerializeField]
	private bool noActionValueAction;

	[SerializeField]
	[HideIf("noActionValueAction")]
	private int fixedActionValue;

	[SerializeField]
	private bool enableStarRequirementAction;

	[SerializeField]
	[ShowIf("enableStarRequirementAction")]
	private StarRequirementAction starRequirementAction;

	[SerializeField]
	private bool enableGainAstrium;

	[SerializeField]
	[ShowIf("enableGainAstrium")]
	private int gainAstriumAmount;

	[SerializeField]
	[ShowIf("enableGainAstrium")]
	private DefaultEffectAction gainAstriumEffectAction;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	public BattleAction BattleAction => battleAction;

	public int MinimumAstriumAmount => minimumAstriumAmount;

	public bool VariableMinimumAstriumAmount => variableMinimumAstriumAmount;

	public int AstriumCost => astriumCost;

	public bool DisableAstriumCostDescription => disableAstriumCostDescription;

	public int FixedActionValue => fixedActionValue;

	public bool EnableGainAstrium => enableGainAstrium;

	public int GainAstriumAmount => gainAstriumAmount;

	public DefaultEffectAction GainAstriumEffectAction => gainAstriumEffectAction;

	private PlayerEffects playerEffects => ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return battleAction.CheckConditionToBeCasted(playerHand, diceOwnerEnum);
	}

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		bool flag = true;
		if (enableStarRequirementAction)
		{
			flag = starRequirementAction.CheckConditionToBeCasted(actionValue);
		}
		if (flag && CheckAstriumAmount(actionValue))
		{
			return battleAction.CheckConditionToBeCasted(actionValue);
		}
		return false;
	}

	public bool CheckAstriumAmount(int actionValue)
	{
		return GetAstriumAmount() >= (variableMinimumAstriumAmount ? actionValue : minimumAstriumAmount);
	}

	private int GetAstriumAmount()
	{
		return ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerAstriumGetAmount(activateFeedback: false);
	}

	public override void CastTargetAmount(GameObject target, int actionValue, GameObject source)
	{
		if (IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(target, delegate
			{
				DefaultCastTargetAmount(target, actionValue, source);
			}));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			DefaultCastTargetAmount(target, actionValue, source);
		}
	}

	protected void DefaultCastTargetAmount(GameObject target, int actionValue, GameObject source, bool ignoreCheckCancelAutoOnDiceCastedOnRuneCasted = false)
	{
		if (noActionValueAction)
		{
			battleAction.CastTarget(target, source);
		}
		else if (fixedActionValue > 0)
		{
			battleAction.CastTargetAmount(target, fixedActionValue, source);
		}
		else
		{
			battleAction.CastTargetAmount(target, actionValue, source);
		}
		CheckGainAstrium();
		CheckAstriumCost();
		if (!ignoreCheckCancelAutoOnDiceCastedOnRuneCasted)
		{
			CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		}
	}

	public override void CastAmount(int actionValue, GameObject source)
	{
		if (IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source, delegate
			{
				DefaultCastAmount(actionValue, source);
			}));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			DefaultCastAmount(actionValue, source);
		}
	}

	protected void DefaultCastAmount(int actionValue, GameObject source)
	{
		if (noActionValueAction)
		{
			battleAction.Cast(source);
		}
		else if (fixedActionValue > 0)
		{
			battleAction.CastAmount(fixedActionValue, source);
		}
		else
		{
			battleAction.CastAmount(actionValue, source);
		}
		CheckGainAstrium();
		CheckAstriumCost();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	public override void Cast(GameObject source)
	{
		if (IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(source, delegate
			{
				DefaultCast(source);
			}));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				DefaultCast(source);
			});
		}
	}

	private void DefaultCast(GameObject source)
	{
		battleAction.Cast(source);
		CheckGainAstrium();
		CheckAstriumCost();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator VFXCoroutine(GameObject vfxOwner, Action afterDelayAction)
	{
		PlaySFX();
		SpawnVFX(GetVFXOwnerPosition(vfxOwner), 4f);
		yield return new WaitForSeconds(vfxDelay);
		afterDelayAction();
	}

	public void CheckAstriumCost()
	{
		if (astriumCost > 0)
		{
			if (astriumCost == 9)
			{
				playerEffects.IsPlayerAstriumRemoveEffect();
			}
			else
			{
				playerEffects.IsPlayerAstriumDecreaseEffect(astriumCost);
			}
		}
	}

	private void CheckGainAstrium()
	{
		if (enableGainAstrium)
		{
			gainAstriumEffectAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, gainAstriumAmount, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		}
	}
}
